-- Fix CTE scope: all financial statement aggregates must be materialized in one WITH chain.
-- The previous rebuild referenced ytd_income outside its CTE statement scope.

create or replace function public.get_financial_statements(p_organization_id uuid,p_period_id uuid)
returns jsonb language plpgsql security definer set search_path=''
as $function$
declare
  v_period record; v_fiscal_month smallint; v_fiscal_year_start date; v_result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not (public.has_org_permission(p_organization_id,'screen.financial_statements.view') or public.has_org_permission(p_organization_id,'statements.view') or public.has_org_permission(p_organization_id,'view')) then raise exception 'Financial statements view permission required'; end if;
  select fp.id,fp.organization_id,fp.period_start,fp.period_end,fp.status,o.fiscal_year_start_month into v_period from public.financial_periods fp join public.organizations o on o.id=fp.organization_id where fp.id=p_period_id and fp.organization_id=p_organization_id;
  if v_period.id is null then raise exception 'Financial period not found'; end if;
  v_fiscal_month:=greatest(1,least(12,v_period.fiscal_year_start_month));
  v_fiscal_year_start:=make_date(extract(year from v_period.period_start)::integer-case when extract(month from v_period.period_start)::integer<v_fiscal_month then 1 else 0 end,v_fiscal_month,1);
  with scoped_facts as (select f.* from public.financial_facts f where f.organization_id=p_organization_id and f.fact_type='actual' and f.status='published' and public.has_org_data_scope(f.organization_id,'legal_entity',f.legal_entity_id) and public.has_org_data_scope(f.organization_id,'branch',f.branch_id) and public.has_org_data_scope(f.organization_id,'department',f.department_id) and public.has_org_data_scope(f.organization_id,'cost_center',f.cost_center_id) and public.has_org_data_scope(f.organization_id,'region',f.region_id) and public.has_org_data_scope(f.organization_id,'product',f.product_id) and public.has_org_data_scope(f.organization_id,'project',f.project_id)), classified as (select f.financial_period_id,fp.period_start,fp.period_end,a.id account_id,a.code,a.name,a.account_type,a.statement_type,a.statement_section,a.statement_subclassification,coalesce(f.debit_minor,0)::bigint debit_minor,coalesce(f.credit_minor,0)::bigint credit_minor from scoped_facts f join public.financial_periods fp on fp.id=f.financial_period_id and fp.organization_id=p_organization_id join public.accounts a on a.id=f.account_id and a.organization_id=p_organization_id), period_income as (select coalesce(sum(case when statement_subclassification='revenue' then credit_minor-debit_minor else 0 end),0)::bigint revenue,coalesce(sum(case when statement_subclassification='cogs' then debit_minor-credit_minor else 0 end),0)::bigint cogs,coalesce(sum(case when statement_subclassification='operating_expense' then debit_minor-credit_minor else 0 end),0)::bigint operating_expenses,coalesce(sum(case when statement_subclassification='other_income' then credit_minor-debit_minor else 0 end),0)::bigint other_income,coalesce(sum(case when statement_subclassification='depreciation_amortization' then debit_minor-credit_minor else 0 end),0)::bigint depreciation_amortization,coalesce(sum(case when statement_subclassification='finance_cost' then debit_minor-credit_minor else 0 end),0)::bigint finance_cost,coalesce(sum(case when statement_subclassification='tax' then debit_minor-credit_minor else 0 end),0)::bigint tax,coalesce(sum(case when statement_subclassification='other_expense' then debit_minor-credit_minor else 0 end),0)::bigint other_expenses,count(distinct account_id) filter(where lower(coalesce(statement_type,''))='income_statement' and statement_subclassification is null)::integer unclassified_count from classified where financial_period_id=p_period_id), ytd_income as (select coalesce(sum(case when statement_subclassification='revenue' then credit_minor-debit_minor else 0 end),0)::bigint revenue,coalesce(sum(case when statement_subclassification='cogs' then debit_minor-credit_minor else 0 end),0)::bigint cogs,coalesce(sum(case when statement_subclassification='operating_expense' then debit_minor-credit_minor else 0 end),0)::bigint operating_expenses,coalesce(sum(case when statement_subclassification='other_income' then credit_minor-debit_minor else 0 end),0)::bigint other_income,coalesce(sum(case when statement_subclassification='depreciation_amortization' then debit_minor-credit_minor else 0 end),0)::bigint depreciation_amortization,coalesce(sum(case when statement_subclassification='finance_cost' then debit_minor-credit_minor else 0 end),0)::bigint finance_cost,coalesce(sum(case when statement_subclassification='tax' then debit_minor-credit_minor else 0 end),0)::bigint tax,coalesce(sum(case when statement_subclassification='other_expense' then debit_minor-credit_minor else 0 end),0)::bigint other_expenses from classified where period_start>=v_fiscal_year_start and period_end<=v_period.period_end), balance_accounts as (select a.code,a.name,a.statement_section,a.account_type,a.statement_subclassification,coalesce(sum(f.debit_minor),0)::bigint debit,coalesce(sum(f.credit_minor),0)::bigint credit,coalesce(sum(f.debit_minor-f.credit_minor),0)::bigint balance from public.accounts a left join classified f on f.account_id=a.id and f.period_end<=v_period.period_end where a.organization_id=p_organization_id and lower(coalesce(a.statement_type,''))='balance_sheet' and a.statement_subclassification in ('asset','liability','equity') group by a.code,a.name,a.statement_section,a.account_type,a.statement_subclassification), totals as (select coalesce(sum(case when statement_subclassification='asset' then balance else 0 end),0)::bigint assets,coalesce(sum(case when statement_subclassification='liability' then -balance else 0 end),0)::bigint liabilities,coalesce(sum(case when statement_subclassification='equity' then -balance else 0 end),0)::bigint equity from balance_accounts), income_json as (select jsonb_build_object('revenue',revenue,'cogs',cogs,'gross_profit',revenue-cogs,'operating_expenses',operating_expenses,'other_income',other_income,'depreciation_amortization',depreciation_amortization,'ebitda',revenue-cogs-operating_expenses+other_income,'ebit',revenue-cogs-operating_expenses+other_income-depreciation_amortization,'finance_cost',finance_cost,'other_expenses',other_expenses,'ebt',revenue-cogs-operating_expenses+other_income-depreciation_amortization-finance_cost-other_expenses,'tax',tax,'net_income',revenue-cogs-operating_expenses+other_income-depreciation_amortization-finance_cost-other_expenses-tax,'unclassified_income_accounts',unclassified_count) as value from period_income), ytd_json as (select jsonb_build_object('revenue',revenue,'cogs',cogs,'gross_profit',revenue-cogs,'operating_expenses',operating_expenses,'other_income',other_income,'depreciation_amortization',depreciation_amortization,'ebitda',revenue-cogs-operating_expenses+other_income,'ebit',revenue-cogs-operating_expenses+other_income-depreciation_amortization,'finance_cost',finance_cost,'other_expenses',other_expenses,'ebt',revenue-cogs-operating_expenses+other_income-depreciation_amortization-finance_cost-other_expenses,'tax',tax,'net_income',revenue-cogs-operating_expenses+other_income-depreciation_amortization-finance_cost-other_expenses-tax) as value from ytd_income), balance_json as (select jsonb_build_object('accounts',coalesce((select jsonb_agg(jsonb_build_object('code',code,'name',name,'section',statement_section,'account_type',account_type,'subclassification',statement_subclassification,'debit',debit,'credit',credit,'balance',balance) order by code) from balance_accounts),'[]'::jsonb),'total_assets',t.assets,'total_liabilities',t.liabilities,'total_equity',t.equity,'current_period_net_income',(ij.value->>'net_income')::bigint,'ytd_net_income',(yj.value->>'net_income')::bigint,'balance_check',t.assets-t.liabilities-t.equity-(yj.value->>'net_income')::bigint) as value from totals t cross join income_json ij cross join ytd_json yj)
  select jsonb_build_object('period',jsonb_build_object('id',v_period.id,'start',v_period.period_start,'end',v_period.period_end,'status',v_period.status),'fiscal_year_start',v_fiscal_year_start,'income_statement',ij.value,'income_statement_ytd',yj.value,'balance_sheet',bj.value,'validation',jsonb_build_object('unclassified_income_accounts',coalesce((ij.value->>'unclassified_income_accounts')::integer,0),'balance_sheet_difference',coalesce((bj.value->>'balance_check')::bigint,0)),'methodology',jsonb_build_object('actuals_only',true,'published_only',true,'balance_sheet_cumulative',true,'income_statement_basis','selected_period','income_statement_ytd_available',true,'fiscal_year_aware',true,'classification_authoritative',true)) into v_result
  from income_json ij cross join ytd_json yj cross join balance_json bj;
  return v_result;
end;
$function$;
revoke all on function public.get_financial_statements(uuid,uuid) from public,anon;
grant execute on function public.get_financial_statements(uuid,uuid) to authenticated;
